<template><section class="trust-panel"><div v-if="info"><h3>{{info.materialReviewed?'出租资格材料已人工审核':'出租资格材料尚未完成审核'}}</h3><p>{{info.scope}}</p><p v-if="info.demo">此房源为演示数据，地图仅作位置参考，不代表该处有实际房屋出租。</p><p v-if="info.details">押{{info.details.depositMonths}}付{{info.details.paymentMonths}} · 服务费{{info.details.serviceFee}}元 · {{info.details.otherFees}}<br/>{{info.details.utilityTerms}}</p></div><button @click="show=!show">{{show?'收起举报':'房源信息有问题？举报'}}</button><form v-if="show" @submit.prevent="report"><label>问题类型<select v-model="category"><option v-for="c in categories" :key="c">{{c}}</option></select></label><label>具体情况<textarea v-model.trim="content" minlength="10" maxlength="2000" rows="4" required placeholder="至少10字，请描述具体问题"/></label><label>证据（选填，最多3份）<input type="file" accept="image/png,image/jpeg,application/pdf" multiple @change="files=[...$event.target.files]"/></label><button :disabled="busy">{{busy?'提交中…':'提交举报'}}</button><RouterLink to="/app/workflow">查看处理进度 →</RouterLink></form><p v-if="message" role="status">{{message}}</p></section></template>
<script setup>
import {ref,watch,onMounted} from 'vue'
import request from '../api/index'
const props=defineProps({houseId:Number}),info=ref(null),show=ref(false),content=ref(''),category=ref('虚假房源'),files=ref([]),busy=ref(false),message=ref(''),categories=['虚假房源','图片不符','价格或费用不符','冒充房东','已出租仍展示','其他']
let version=0
async function load(){const v=++version;info.value=null;show.value=false;message.value='';try{const r=await request.get('/trust/public/'+props.houseId);if(v===version)info.value=r.data}catch{}}
async function report(){busy.value=true;message.value='';try{if(files.value.length>3)throw Error('证据最多3份');const evidenceIds=[];for(const f of files.value){if(f.size>8*1024*1024)throw Error('单份文件不得超过8MB');const data=new FormData();data.append('file',f);data.append('kind','EVIDENCE');evidenceIds.push((await request.post('/trust/upload',data,{timeout:120000})).data.id)}await request.post('/trust/report/'+props.houseId,{category:category.value,content:content.value,evidenceIds});message.value='举报已提交，请到我的办理进度查看答复。';show.value=false;content.value='';files.value=[]}catch(e){message.value=e.response?.data?.message||e.message}finally{busy.value=false}}
watch(()=>props.houseId,load);onMounted(load)
</script>
<style scoped>.trust-panel{border:1px solid var(--jade-line);background:#f1f5ed;padding:24px;margin-top:28px;border-radius:6px}.trust-panel h3{font-size:17px}.trust-panel p{font-size:13px;line-height:1.9;margin:12px 0;color:var(--jade-muted)}.trust-panel button,.trust-panel select,.trust-panel textarea{padding:10px;border:1px solid var(--jade-line);background:white;border-radius:4px;color:var(--jade-700)}.trust-panel label{display:block;margin:16px 0;font-size:13px}.trust-panel select,.trust-panel textarea{display:block;width:100%;margin-top:8px}.trust-panel a{margin-left:16px;font-size:13px}</style>
